 const a=attach(from,to),b=attach(to,from);if(a.near.segment===b.near.segment){const cost=serviceRoadDistance(nodes[a.id],nodes[b.id]);edges[a.id].push({id:b.id,cost});edges[b.id].push({id:a.id,cost});}
